using System.Text.Json;
using Forge.Network.Authoring;
using Forge.Network.Operations;
using Forge.Network.Sessions;
namespace Forge.LiveDirector.Authoring;

public sealed record LiveDirectorOperationsProfile(Guid Id, int SchemaVersion, string Provenance, NetworkAuthorityScope AuthorityScope, long ServerRevision, string AuditIdentity, bool RequiredAtRuntime,
 bool IndexedSearch, bool NextMatch, bool SavedQueries, bool StableDeepLinks, bool VisualFocus,
 bool RegisteredCommandsOnly, bool SignedSnippets, bool RejectShellProcessFilesystemNetwork, bool ForgeScriptServerAdapter,
 IReadOnlyList<string> VariableKinds, bool VariableHistory, bool PersistentStateAdapter,
 IReadOnlyList<string> SceneFacets, bool MandatoryRollback, bool SceneRuntimeAdapters,
 IReadOnlyList<string> VisibilityLayers, bool SelectedPlayerProjection, bool ViewportOverlayAdapter)
{
    public static LiveDirectorOperationsProfile CreateDefault(string provenance = "openrpg:r129") => new(Guid.Parse("d1290000-0000-4000-8000-000000000001"), 1, provenance, NetworkAuthorityScope.Server, 0, "live.director", false,
    true, true, true, true, true, true, true, true, true, ["bool", "number", "enum", "string"], true, true, ["spawns", "dialogue", "music", "weather", "triggers"], true, true, ["hidden-objects", "secrets", "navigation", "encounters"], true, true);
}
public static class LiveDirectorOperationsValidator
{
    public static IReadOnlyList<NetworkDiagnostic> Validate(LiveDirectorOperationsProfile p) { var d = new List<NetworkDiagnostic>(); if (p.Id == Guid.Empty) A("LIVE_OPS_UUID_INVALID", "/liveDirector/operations", p.Id, d); if (p.SchemaVersion != 1) A("LIVE_OPS_SCHEMA_UNSUPPORTED", "/liveDirector/operations/schemaVersion", p.Id, d); if (string.IsNullOrWhiteSpace(p.Provenance) || p.AuthorityScope != NetworkAuthorityScope.Server || p.ServerRevision < 0 || string.IsNullOrWhiteSpace(p.AuditIdentity)) A("LIVE_OPS_IDENTITY_INVALID", "/liveDirector/operations/identity", p.Id, d); if (!p.IndexedSearch || !p.NextMatch || !p.SavedQueries || !p.StableDeepLinks || !p.VisualFocus) A("LIVE_SEARCH_POLICY_INVALID", "/liveDirector/operations/search", p.Id, d); if (!p.RegisteredCommandsOnly || !p.SignedSnippets || !p.RejectShellProcessFilesystemNetwork || !p.ForgeScriptServerAdapter) A("LIVE_SCRIPT_POLICY_INVALID", "/liveDirector/operations/script", p.Id, d); if (p.VariableKinds.Count != 4 || !p.VariableHistory || !p.PersistentStateAdapter) A("LIVE_VARIABLE_POLICY_INVALID", "/liveDirector/operations/variables", p.Id, d); if (p.SceneFacets.Count != 5 || !p.MandatoryRollback || !p.SceneRuntimeAdapters) A("LIVE_SCENE_POLICY_INVALID", "/liveDirector/operations/scenes", p.Id, d); if (p.VisibilityLayers.Count != 4 || !p.SelectedPlayerProjection || !p.ViewportOverlayAdapter) A("LIVE_VISIBILITY_POLICY_INVALID", "/liveDirector/operations/visibility", p.Id, d); return d; }
    private static void A(string code, string path, Guid id, ICollection<NetworkDiagnostic> d) => d.Add(new(code, path, "Required governed operation capability is missing.", id));
}
public sealed record LiveDirectorOperationsCommand(Guid CommandId, int SchemaVersion, string Provenance, long ExpectedRevision, string ActorId, NetworkRole Role, bool Apply, LiveDirectorOperationsProfile Candidate);
public sealed record LiveDirectorOperationsResult(bool Succeeded, bool Applied, LiveDirectorOperationsProfile Profile, IReadOnlyList<NetworkDiagnostic> Diagnostics, string SemanticDiff, string AuditEntry);
public sealed class LiveDirectorOperationsHistory
{
    private readonly Stack<LiveDirectorOperationsProfile> u = []; private readonly Stack<LiveDirectorOperationsProfile> r = []; public LiveDirectorOperationsHistory(LiveDirectorOperationsProfile p) { if (LiveDirectorOperationsValidator.Validate(p).Count != 0) throw new ArgumentException("LIVE_OPS_INITIAL_INVALID"); Current = p; }
    public LiveDirectorOperationsProfile Current { get; private set; }
    public LiveDirectorOperationsResult Execute(LiveDirectorOperationsCommand c) { var d = LiveDirectorOperationsValidator.Validate(c.Candidate).ToList(); if (c.CommandId == Guid.Empty || c.SchemaVersion != 1 || string.IsNullOrWhiteSpace(c.Provenance)) d.Add(new("LIVE_OPS_COMMAND_INVALID", "/liveDirector/operations/command", "Command identity required.", c.CommandId)); if (string.IsNullOrWhiteSpace(c.ActorId) || c.Role is not (NetworkRole.GameMaster or NetworkRole.Administrator)) d.Add(new("LIVE_OPS_PERMISSION_DENIED", "/liveDirector/operations/audit/actor", "GM required.", c.Candidate.Id)); if (c.ExpectedRevision != Current.ServerRevision || c.Candidate.ServerRevision != Current.ServerRevision + 1) d.Add(new("LIVE_OPS_REVISION_STALE", "/liveDirector/operations/serverRevision", "Revision must advance once.", c.Candidate.Id)); const string diff = "search,script,variables,scenes,visibility"; if (d.Count != 0) return X(false, false, Current, d, diff, "rejected", c.ActorId); if (!c.Apply) return X(true, false, Current, [], diff, "previewed", c.ActorId); u.Push(Current); Current = c.Candidate; r.Clear(); return X(true, true, Current, [], diff, "applied", c.ActorId); }
    public LiveDirectorOperationsResult Undo(string a, NetworkRole role) => M(u, r, a, role, "undo"); public LiveDirectorOperationsResult Redo(string a, NetworkRole role) => M(r, u, a, role, "redo"); private LiveDirectorOperationsResult M(Stack<LiveDirectorOperationsProfile> f, Stack<LiveDirectorOperationsProfile> t, string a, NetworkRole role, string action) { if (f.Count == 0 || role is not (NetworkRole.GameMaster or NetworkRole.Administrator)) return X(false, false, Current, [new("LIVE_OPS_HISTORY_DENIED", "/liveDirector/operations/history", "Unavailable.", Current.Id)], "no changes", "rejected", a); t.Push(Current); Current = f.Pop(); return X(true, true, Current, [], "operations", $"compensated:{action}", a); }
    private static LiveDirectorOperationsResult X(bool ok, bool ap, LiveDirectorOperationsProfile p, IReadOnlyList<NetworkDiagnostic> d, string diff, string action, string actor) => new(ok, ap, p, d, diff, $"{action}:live.operations:actor={actor}:revision={p.ServerRevision}");
}
public sealed class LiveDirectorOperationsStore { private static readonly JsonSerializerOptions O = new() { PropertyNamingPolicy = JsonNamingPolicy.CamelCase, WriteIndented = true }; public string Serialize(LiveDirectorOperationsProfile p) { var d = LiveDirectorOperationsValidator.Validate(p); if (d.Count != 0) throw new InvalidDataException(d[0].Code); return JsonSerializer.Serialize(p, O).Replace("\r\n", "\n", StringComparison.Ordinal) + "\n"; } public LiveDirectorOperationsProfile Deserialize(string j) { var p = JsonSerializer.Deserialize<LiveDirectorOperationsProfile>(j, O) ?? throw new InvalidDataException("LIVE_OPS_EMPTY"); var d = LiveDirectorOperationsValidator.Validate(p); if (d.Count != 0) throw new InvalidDataException(d[0].Code); return p; } }
public sealed record LiveDirectorOperationsResolution(bool Available, LiveDirectorOperationsProfile? Profile, IReadOnlyList<NetworkDiagnostic> Diagnostics); public static class LiveDirectorOperationsRuntimeAdapter { public static LiveDirectorOperationsResolution Resolve(LiveDirectorOperationsProfile? p, bool required) { if (p is null) return required ? new(false, null, [new("LIVE_OPS_REQUIRED_MISSING", "/liveDirector/operations", "Required profile missing.")]) : new(false, null, []); var d = LiveDirectorOperationsValidator.Validate(p); return new(d.Count == 0, d.Count == 0 ? p : null, d); } }
public readonly record struct LiveDirectorOperationsHandle(Guid ProfileId, int Generation); public sealed record LiveDirectorOperationsSnapshot(Guid Id, long Revision, int VariableKinds, int SceneFacets, int VisibilityLayers, bool VisualFocus); public sealed class LiveDirectorOperationsScriptService(LiveDirectorOperationsProfile p) { public LiveDirectorOperationsHandle Handle { get; } = new(p.Id, 1); public LiveDirectorOperationsSnapshot Read(LiveDirectorOperationsHandle h) { if (h.ProfileId != p.Id || h.Generation != 1) throw new InvalidOperationException("LIVE_OPS_HANDLE_INVALID"); return new(p.Id, p.ServerRevision, p.VariableKinds.Count, p.SceneFacets.Count, p.VisibilityLayers.Count, p.VisualFocus); } }
